<?php
/** Minimal dependency-free XLSX writer for the accounting export. */
final class Decka_Xlsx {
    private static function xml(string $value):string {return htmlspecialchars($value,ENT_XML1|ENT_QUOTES,'UTF-8');}
    private static function col(int $index):string {$out='';for($index++;$index>0;$index=intdiv($index-1,26))$out=chr(65+(($index-1)%26)).$out;return $out;}
    public static function build(array $headers,array $rows):string {
        if(!class_exists('ZipArchive'))throw new RuntimeException('Serwer nie obsługuje generowania plików XLSX (brak ZipArchive).');
        $sheet='<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>';
        foreach($headers as $i=>$header)$sheet.='<col min="'.($i+1).'" max="'.($i+1).'" width="'.min(45,max(12,mb_strlen($header)+3)).'" customWidth="1"/>';
        $sheet.='</cols><sheetData>';
        $all=array_merge([$headers],$rows);foreach($all as $ri=>$row){$sheet.='<row r="'.($ri+1).'">';foreach(array_values($row) as $ci=>$value){$ref=self::col($ci).($ri+1);if($ri>0&&is_int($value))$sheet.='<c r="'.$ref.'" s="2"><v>'.($value/100).'</v></c>';else $sheet.='<c r="'.$ref.'" t="inlineStr" s="'.($ri===0?'1':'0').'"><is><t xml:space="preserve">'.self::xml((string)$value).'</t></is></c>';}$sheet.='</row>';}$last=self::col(count($headers)-1).count($all);
        $sheet.='</sheetData><autoFilter ref="A1:'.$last.'"/></worksheet>';
        $files=['[Content_Types].xml'=>'<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>','_rels/.rels'=>'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>','xl/workbook.xml'=>'<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Zamówienia" sheetId="1" r:id="rId1"/></sheets></workbook>','xl/_rels/workbook.xml.rels'=>'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>','xl/styles.xml'=>'<?xml version="1.0" encoding="UTF-8"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><numFmts count="1"><numFmt numFmtId="164" formatCode="# ##0.00 [$zł-pl-PL]"/></numFmts><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><color rgb="FFFFFFFF"/><name val="Calibri"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF19569D"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="3"><xf xfId="0"/><xf xfId="0" fontId="1" fillId="2" applyFont="1" applyFill="1"/><xf xfId="0" numFmtId="164" applyNumberFormat="1"/></cellXfs></styleSheet>','xl/worksheets/sheet1.xml'=>'<?xml version="1.0" encoding="UTF-8"?>'.$sheet];
        $tmp=tempnam(sys_get_temp_dir(),'decka-xlsx-');if(!$tmp)throw new RuntimeException('Nie można utworzyć pliku raportu.');$zip=new ZipArchive();if($zip->open($tmp,ZipArchive::OVERWRITE)!==true){unlink($tmp);throw new RuntimeException('Nie można utworzyć archiwum XLSX.');}foreach($files as $name=>$body)$zip->addFromString($name,$body);$zip->close();$result=file_get_contents($tmp);unlink($tmp);if($result===false)throw new RuntimeException('Nie można odczytać raportu XLSX.');return $result;
    }
}
